package com.privacyguardian.config;
import com.privacyguardian.security.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.List;
@Component public class AuthFilter extends GenericFilter { private final JwtService jwt; public AuthFilter(JwtService jwt){this.jwt=jwt;} public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.parse(h.substring(7));var a=new UsernamePasswordAuthenticationToken(c.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+c.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}chain.doFilter(req,res);} }
